"""5192 Б (рядок 6429): виклик розбору речі ДО проти виклику рядка ПІСЛЯ — символи (токени з GEMMA_TOKENIZER), виклики, години."""
import glob, json, os, re, statistics as С, sys
Д = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path[:0] = [Д, os.path.join(Д, 'прилади')]; os.chdir(Д)
import каталог_розбір as КР, каталог_розбір_прогін as П, фід_каталог as ФК, фід_розбір as ФР, розбір_рядків_5192 as Б
Т = None
if os.environ.get('GEMMA_TOKENIZER'):
    from tokenizers import Tokenizer; Т = Tokenizer.from_file(os.environ['GEMMA_TOKENIZER'])
ток = lambda т: [len(е.ids) for і in range(0, len(т), 500) for е in Т.encode_batch(т[і:і + 500], add_special_tokens=False)] if Т else []
def мп(ч):
    """медіана / 95-й перцентиль."""
    ч = sorted(ч); return '%d / %d' % (С.median(ч), ч[int(.95 * (len(ч) - 1))]) if ч else '—'
def рядок(назва, тексти, схема):
    print('%-34s %15s %15s %8d' % (назва, мп(map(len, тексти)), мп(ток(тексти)), схема))
рядки, речі = Б.рядки_каталогу(); ет = set(Б.ід_еталону()); пари = sum(len(в) for в in json.load(__import__('gzip').open(Б.РЯДКИ)).values())
ключі = sorted({к for к, _ in рядки.values()}); офери = {o['id']: o for o in ФР.читати_yml(ФК.каталог_на_диску(), показ=False)[0]}
print('пар (ключ, значення) у рядки_5192: %d; словами крамниці бодай в одній речі: %d (ключів %d); речей з рядками %d; рядків 60 речей еталону: %d'
      % (пари, len(рядки), len(ключі), len(речі), len(Б.вибрати(рядки, речі, 0))))
print('%-34s %15s %15s %8s' % ('виклик (медіана / 95-й перцентиль)', 'символів', 'токенів', 'граматика'))
рядок('ДО: річ, повний скелет (еталон 60)', [json.dumps(КР.промпт(офери[і]), ensure_ascii=False) for і in ет if і in офери], len(json.dumps(КР.схема_відповіді())))
рядок('ДО: річ, увесь каталог', [json.dumps(КР.промпт(o), ensure_ascii=False) for o in офери.values()], len(json.dumps(КР.схема_відповіді())))
пром = lambda гр: [json.dumps(Б.промпт_рядка(к, з, гр), ensure_ascii=False) for к, з in рядки.values()]
рядок('ПІСЛЯ: рядок, усі %d груп' % len(Б.ГРУПИ), пром(list(Б.ГРУПИ)), len(json.dumps(Б.схема_рядка(Б.шляхи_груп(list(Б.ГРУПИ))))))
for г in Б.ГРУПИ: рядок('ПІСЛЯ: рядок, група %s' % г, пром([г]), len(json.dumps(Б.схема_рядка(Б.шляхи_груп([г])))))
рядок('ПІСЛЯ: ключ → групи (раз на ключ)', [json.dumps(Б.промпт_ключа(к, Б.зразки_ключа(к, рядки)), ensure_ascii=False) for к in ключі], len(json.dumps(Б.схема_ключа())))
# Години — оцінка, не вимір: секунд виклику на знак відповіді в 404 (3 × 60 речей, parallel 2), відповідь рядка — «усе unknown» (найкоротша) і заглушка з цитатою-значенням.
вв = [р for а in sorted(glob.glob('../аудит/розбір_каталогу/404_а?/прогін.json')) for р in json.load(open(а, encoding='utf-8'))['речі']]
зн = sum(р['секунд'] for р in вв) / sum(р['знаків_відповіді'] for р in вв)
стіна = [int(с) / 60 for с in re.findall(r'а\d (\d+) с', open('../аудит/розбір_каталогу/404_ПІДСУМОК.txt', encoding='utf-8').read())]
def відп(гр, цитата):
    """знаків відповіді рядка з групами `гр`: заглушка граматики, цитата — значення рядка чи порожня (тоді коди → unknown)."""
    т = Б.тіло({}, Б.схема_рядка(Б.шляхи_груп(гр)), '-'); в = json.loads(Б.заглушка(т, цитата)[0])
    if not цитата: в = json.loads(re.sub(r'"(value|unit)": "[^"]*"', r'"\1": "unknown"', json.dumps(в)))
    return len(json.dumps(в, ensure_ascii=False))
год = lambda гр, ц: (sum(відп(гр, Б._значення(з)[:КР.СТЕЛЯ_ЦИТАТИ] if ц else '') for _, з in рядки.values()) + len(ключі) * 60) * зн / П.ПАРАЛЕЛЬНО / 3600
print('викликів на каталог: ДО 12 426 записів (11 887 речей); ПІСЛЯ до %d рядків + %d ключів (рядки ключів без груп не йдуть)' % (len(рядки), len(ключі)))
print('години ноутбука (%.4f с на знак відповіді, parallel %d): ДО %.1f–%.1f (стіна 404, %.1f–%.1f с на річ); ПІСЛЯ, одна група на рядок — %s; усі %d груп — %.1f–%.1f'
      % (зн, П.ПАРАЛЕЛЬНО, 12426 * min(стіна) / 3600, 12426 * max(стіна) / 3600, min(стіна), max(стіна),
         ', '.join('%s %.1f–%.1f' % (г, год([г], 0), год([г], 1)) for г in Б.ГРУПИ), len(Б.ГРУПИ), год(list(Б.ГРУПИ), 0), год(list(Б.ГРУПИ), 1)))
